#!/bin/sh
set -eu
ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)
APP="$ROOT/adhook/app/src/main"
HTML="$APP/assets/webroot/index.html"
fail(){ echo "FAIL: $*" >&2; exit 1; }

[ -s "$HTML" ] || fail "complete FX WebUI was not staged into APK assets"
grep -q "FX: merged pageAd into pageHosts" "$HTML" || fail "legacy Ad content was not merged into the Hosts page"
grep -q "mitmTrafficEnable" "$HTML" || fail "merged Ad certificate/MITM controls are missing"
grep -q "hostsOpenEditor" "$HTML" || fail "local system Hosts editor is missing from the merged page"
[ "$(wc -c < "$HTML" | tr -d ' ')" -gt 500000 ] || fail "FX WebUI asset is unexpectedly truncated"
for page in pageVpn pageAd pageHosts pagePrivacy pageScript pageMore; do
  grep -q "id=\"$page\"" "$HTML" || fail "missing migrated UI page: $page"
done
for panel in vpnPanel rootPanel advPanel netPanel permPanel sensorPanel locationPanel devicePanel mediaPanel filePanel notifyPanel kernelPanel miscPanel crashPanel stylePanel langPanel; do
  grep -q "id=\"$panel\"" "$HTML" || fail "missing migrated settings panel: $panel"
done
for marker in fxHookAppList fxHookSync builtinCerts mitmTrafficEnable hostsOpenEditor vpnSubUpdateAll; do
  grep -q "$marker" "$HTML" || fail "missing migrated feature marker: $marker"
done

ACTIVITY="$APP/java/de/privacyguard/adhook/MainActivity.java"
BRIDGE="$APP/java/de/privacyguard/adhook/RootBridge.java"
HOOK="$APP/java/de/privacyguard/adhook/AdVisibilityHook.java"
ROOT_ACCESS="$APP/java/de/privacyguard/adhook/RootAccess.java"
[ -s "$ACTIVITY" ] || fail "MainActivity missing"
[ -s "$BRIDGE" ] || fail "RootBridge missing"
[ -s "$ROOT_ACCESS" ] || fail "RootAccess missing"
[ -s "$HOOK" ] || fail "unified Ad Hook runtime missing"
grep -Fq "AUTO_AD_TARGET" "$HOOK" || fail "built-in automatic Ad target missing"
grep -Fq "final boolean adsForPackage = adsEnabled;" "$HOOK" || fail "Ad runtime still depends on per-app category switches"
grep -Fq "adsEnabled = true;" "$HOOK" || fail "legacy Ad master switch still controls automatic recognition"
grep -Fq "return AUTO_AD_TARGET;" "$HOOK" || fail "Ad runtime still requires an explicit target list"
grep -Fq "adDetection=automatic(splash/feed/overlay)" "$HOOK" || fail "automatic Ad classifier is not reported by runtime"
grep -q 'WebViewAssetLoader' "$ACTIVITY" || fail "secure app asset loader missing"
grep -q 'appassets.androidplatform.net/assets/webroot/index.html' "$ACTIVITY" || fail "WebUI is not loaded from app-owned assets"
grep -q 'setAllowFileAccess(false)' "$ACTIVITY" || fail "WebView file access must remain disabled"
grep -q 'setAllowUniversalAccessFromFileURLs(false)' "$ACTIVITY" || fail "universal file URL access must remain disabled"
grep -q 'window.ksu={exec:function' "$ACTIVITY" || fail "KernelSU WebUI compatibility bridge missing"
grep -q 'window.showSaveFilePicker' "$ACTIVITY" || fail "native export bridge shim missing"
grep -q 'onShowFileChooser' "$ACTIVITY" || fail "native import file picker missing"
grep -q 'openHookManager' "$BRIDGE" || fail "native Hook manager entry missing"
grep -q 'FXRoot.exec' "$ACTIVITY" || fail "WebUI root execution shim missing"
grep -q 'CALLBACK' "$BRIDGE" || fail "callback name validation missing"
grep -q '@JavascriptInterface' "$BRIDGE" || fail "JavaScript bridge annotation missing"
grep -q 'saveBase64' "$BRIDGE" || fail "Android Downloads export bridge missing"
grep -Fq 'String[] labels = {"VPN", "Ad", "隐私", "脚本", "Hook", "设置"}' "$ACTIVITY" || fail "six bottom navigation tabs (merged Ads/Hosts plus Settings) missing"
grep -q 'fx-native-nav-hide' "$ACTIVITY" || fail "duplicate WebUI bottom navigation must be hidden"
grep -q '"pageScript", "pageMore"' "$ACTIVITY" || fail "sixth Settings tab must route to advanced Settings"
grep -q 'case "pageAd": tab = "hosts"; break;' "$ACTIVITY" || fail "Ad tab must open the merged Hosts/rules page"
! grep -Fq "getElementById('cardHostsLocal')" "$ACTIVITY" || fail "Ad tab must show the merged page from its top, not hide rules above Hosts"
grep -q 'showHookHub()' "$ACTIVITY" || fail "Hook tab does not open the Hook permission hub"
grep -q 'hookTargetVisible' "$ACTIVITY" || fail "Android back navigation must return from target config to app list"
grep -q 'org.lsposed.manager' "$ACTIVITY" || fail "LSPosed Manager detection/launch missing"
grep -q 'ACTION_ACCESSIBILITY_SETTINGS' "$ACTIVITY" || fail "Android accessibility settings entry missing"
grep -q 'FxAccessibilityService' "$ROOT/adhook/app/src/main/AndroidManifest.xml" || fail "accessibility service missing from source manifest"
grep -q 'BIND_ACCESSIBILITY_SERVICE' "$ROOT/adhook/app/src/main/AndroidManifest.xml" || fail "accessibility bind permission missing"
grep -q 'fx_accessibility_service' "$ROOT/adhook/app/src/main/AndroidManifest.xml" || fail "accessibility service metadata missing"
grep -q 'canRetrieveWindowContent="false"' "$ROOT/adhook/app/src/main/res/xml/fx_accessibility_service.xml" || fail "accessibility service must not inspect screen content"
grep -q 'onAccessibilityEvent(AccessibilityEvent event)' "$ROOT/adhook/app/src/main/java/de/privacyguard/adhook/FxAccessibilityService.java" || fail "accessibility event callback missing"
grep -q 'Intentionally observe no event payload' "$ROOT/adhook/app/src/main/java/de/privacyguard/adhook/FxAccessibilityService.java" || fail "accessibility service must not inspect event content"
grep -q 'FxAccessibilityService' "$ROOT/fx-patches/merge_hook_single_apk.py" || fail "APK merge would drop accessibility service"
grep -q 'xposedmodule' "$ROOT/fx-patches/merge_hook_single_apk.py" || fail "LSPosed module metadata missing from merged APK"
grep -q 'new ProcessBuilder("su", "-c", command)' "$ROOT_ACCESS" || fail "KernelSU su executor missing"
grep -q 'command.length() > 131072' "$ROOT_ACCESS" || fail "Root command cap must support 87 KiB config chunks"
grep -q 'command.length() > 131072' "$BRIDGE" || fail "WebView bridge command cap must support 87 KiB config chunks"
grep -q 'PG_WRITE_SLICE=87376' "$HTML" || fail "settings.conf chunk writer contract missing"
grep -q '110000L' "$BRIDGE" || fail "root command timeout must finish before the WebUI callback timeout"
grep -q "androidx.webkit:webkit:1.12.1" "$ROOT/adhook/app/build.gradle" || fail "WebViewAssetLoader dependency missing"
grep -q 'android.permission.INTERNET' "$ROOT/adhook/app/src/main/AndroidManifest.xml" || fail "network permission missing"
grep -q "github.event_name == 'workflow_dispatch'" "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "final package must require an explicit workflow dispatch"
grep -q "vars.FX_FULL_APP_MIGRATION_COMPLETE == 'true'" "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "final package must require migration sign-off variable"
grep -q 'merge_hook_single_apk.py' "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "KernelSU workflow must build both Hook entrypoints in one APK"
grep -q 'FX-Hook-apk' "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "the exact embedded APK must be uploaded separately"
grep -q 'ZIP_APK_SHA' "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "KernelSU ZIP embedded APK checksum verification missing"
grep -q 'cancel-in-progress: true' "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "superseded parallel package builds must be cancelled"
grep -q 'Restore module sources, merge Hook entrypoints, and stage WebUI (no compile)' "$ROOT/.github/workflows/build-fx-adhook.yml" || fail "non-compiling APP migration validation workflow missing"
! grep -Eq 'assembleDebug|testDebugUnitTest' "$ROOT/.github/workflows/build-fx-adhook.yml" || fail "duplicate APK compilation must be removed"
grep -q 'Stage complete FX WebUI inside the APK' "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "KernelSU APK WebUI staging missing"
grep -q 'Retire the old module WebUI entrypoint' "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "parallel module WebUI retirement missing"
grep -q 'FX 管理界面已迁移到 APP' "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "module WebUI migration notice missing"
grep -q 'assets/webroot/index.html' "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "complete WebUI missing from packaged APK assertion"
grep -q 'FXUnifiedHook.zip-entry.apk' "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "final ZIP APK payload inspection missing"
suite_line=$(grep -n 'Run complete FX host regression suite' "$ROOT/.github/workflows/build-fx-kernelsu.yml" | cut -d: -f1)
retire_line=$(grep -n 'Retire the old module WebUI entrypoint' "$ROOT/.github/workflows/build-fx-kernelsu.yml" | cut -d: -f1)
[ -n "$suite_line" ] && [ -n "$retire_line" ] && [ "$suite_line" -lt "$retire_line" ] || fail "module WebUI must be retired only after original UI regression suite"
grep -q 'android:label="FX"' "$ROOT/fx-patches/merge_hook_single_apk.py" || fail "APK merge does not preserve FX application label"
echo "PASS: one FX APK owns the complete UI, Root bridge, native Hook entry, and exact KernelSU ZIP payload"
